structs.value_change_t:
typedef struct
{
    timestamp_t timestamp;
    char value[64];
} value_change_t;

structs.signal_t:
typedef struct
{
    char name[32];
    size_t size;
    value_change_t value_changes[4096];
    size_t changes_count;
} signal_t;

structs.timescale_t:
typedef struct
{
    char unit[8];
    size_t scale;
} timescale_t;

structs.vcd_t:
typedef struct
{
    size_t signals_count;
    signal_t signals[32];
    char date[64];
    char version[64];
    timescale_t timescale;
} vcd_t;

enums.state_t:
typedef enum
{
    BEFORE_MODULE_DEFINITIONS,
    INSIDE_TOP_MODULE,
    INSIDE_INNER_MODULES
} state_t;

functions.vcd_read_from_path:
vcd_t *vcd_read_from_path(char *path)
{
    FILE *file = fopen(path, "r");
    if (file == ((void *)0))
        return ((void *)0);
    vcd_t *vcd = new_vcd();
    timestamp_t current_timestamp = 0;
    state_t state = BEFORE_MODULE_DEFINITIONS;
    int character = 0;
    while ((character = fgetc(file)) != (-1))
    {
        if (character == '$')
        {
            _Bool successful = parse_instruction(file, vcd, &state);
            if (successful)
                continue;
        }
        else if (character == '#')
        {
            _Bool successful = parse_timestamp(file, &current_timestamp);
            if (successful)
                continue;
        }
        else if ((strchr("-0123456789zZxXbU", (character))))
        {
            ungetc(character, file);
            _Bool successful = parse_assignment(file, vcd, current_timestamp);
            if (successful)
                continue;
        }
        else if (((*__ctype_b_loc())[(int)((character))] & (unsigned short int)_ISspace))
            continue;
        fclose(file);
        free(vcd);
        return ((void *)0);
    }
    fclose(file);
    return vcd;
}

functions.vcd_get_signal_by_name:
signal_t *vcd_get_signal_by_name(vcd_t *vcd, const char *signal_name)
{
    for (int i = 0; i < vcd->signals_count; ++i)
    {
        if (strcmp(vcd->signals[i].name, signal_name) == 0)
            return &vcd->signals[i];
    }
    return ((void *)0);
}

functions.vcd_signal_get_value_at_timestamp:
char *vcd_signal_get_value_at_timestamp(signal_t *signal, timestamp_t timestamp)
{
    char *previous_value = ((void *)0);
    for (int i = 0; i < signal->changes_count; ++i)
    {
        value_change_t *value_change = &signal->value_changes[i];
        if (timestamp < value_change->timestamp)
            break;
        previous_value = value_change->value;
    }
    return previous_value;
}

functions.parse_instruction:
_Bool parse_instruction(FILE *file, vcd_t *vcd, state_t *state)
{
    char instruction[512];
    if (fscanf(file, "%s", instruction) != 1)
        return 0;
    if (strcmp(instruction, "end") == 0 || strcmp(instruction, "dumpvars") == 0 || strcmp(instruction, "dumpall") == 0)
        return 1;
    if (strcmp(instruction, "scope") == 0)
    {
        switch (*state)
        {
        case BEFORE_MODULE_DEFINITIONS:
            *state = INSIDE_TOP_MODULE;
            break;
        case INSIDE_TOP_MODULE:
            *state = INSIDE_INNER_MODULES;
            break;
        default:
            break;
        }
        fscanf(file, "\n%*[^$]");
        return 1;
    }
    if (strcmp(instruction, "scope") == 0 || strcmp(instruction, "upscope") == 0 ||
        strcmp(instruction, "enddefinitions") == 0 || strcmp(instruction, "comment") == 0)
    {
        fscanf(file, "\n%*[^$]");
        return 1;
    }
    if (strcmp(instruction, "var") == 0)
    {
        if (*state == INSIDE_INNER_MODULES)
        {
            fscanf(file, " %*[^\n]\n");
            return 1;
        }
        signal_t *signal = &vcd->signals[vcd->signals_count];
        vcd->signals_count += 1;
        char signal_id[32];
        fscanf(file, " %*s %zu %[^ ] %[^ $]%*[^$]", &signal->size, signal_id, signal->name);
        int index = get_signal_index(signal_id);
        if (vcd->signals[index].size != 0)
            return 1;
        return 1;
    }
    if (strcmp(instruction, "date") == 0)
    {
        fscanf(file, "\n%[^$\n]", vcd->date);
        return 1;
    }
    if (strcmp(instruction, "version") == 0)
    {
        fscanf(file, "\n%[^$\n]", vcd->version);
        return 1;
    }
    if (strcmp(instruction, "timescale") == 0)
    {
        fscanf(file, "\n\t%zu%[^$\n]", &vcd->timescale.scale, vcd->timescale.unit);
        return 1;
    }
    return 0;
}

functions.parse_timestamp:
_Bool parse_timestamp(FILE *file, timestamp_t *timestamp)
{
    _Bool successful = fscanf(file, "%u", timestamp) == 1;
    return successful;
}

functions.parse_assignment:
_Bool parse_assignment(FILE *file, vcd_t *vcd, timestamp_t timestamp)
{
    char buffer[512];
    char value[64];
    char signal_id[32];
    fscanf(file, "%[^\n]", buffer);
    _Bool is_vector = strchr("01xXzZ", buffer[0]) == ((void *)0);
    char *assignment_format_string = is_vector ? "%[^ ] %[^\n]" : "%1s%[^\n]";
    if (sscanf(buffer, assignment_format_string, value, signal_id) != 2)
        return 0;
    if (strlen(signal_id) > 1)
        return 1;
    size_t index = get_signal_index(signal_id);
    if (index == -1 || index >= vcd->signals_count)
        return 1;
    size_t changes_count = vcd->signals[index].changes_count;
    vcd->signals[index].value_changes[changes_count].timestamp = timestamp;
    strncpy(vcd->signals[index].value_changes[changes_count].value, value, 64);
    vcd->signals[index].changes_count += 1;
    return 1;
}

functions.get_signal_index:
int get_signal_index(const char *string)
{
    int id = *string - '!';
    if (id >= 32)
        return -1;
    return id;
}
